BEGIN;
CREATE TABLE IF NOT EXISTS public.transportistas (
    transportista_id TEXT NOT NULL PRIMARY KEY,
    nombre TEXT
);

CREATE TABLE IF NOT EXISTS public.vehiculos (
    placa TEXT NOT NULL PRIMARY KEY,
    transportista_id TEXT REFERENCES public.transportistas(transportista_id),
    estado TEXT,
    longitud_m DOUBLE PRECISION,
    ancho_m DOUBLE PRECISION,
    alto_m DOUBLE PRECISION,
    volumen_m3 DOUBLE PRECISION,
    color TEXT,
    marca TEXT,
    observaciones TEXT,
    producto_terminado BOOLEAN,
    materia_prima BOOLEAN,
    productos_varios BOOLEAN,
    carton BOOLEAN,
    papel BOOLEAN,
    bodega BOOLEAN,
    abastecimientos BOOLEAN,
    usuario_creador TEXT,
    fecha_creacion TIMESTAMP WITHOUT TIME ZONE,
    registros_origen BIGINT
);

